<?php
declare(strict_types=1);
require dirname(__DIR__).'/config/bootstrap.php';
use InaudisVote\Core\Authorization;
use InaudisVote\Core\Csrf;
use InaudisVote\Services\OrganizationService;
$user=Authorization::requireRoles(['admin']);
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Csrf::validate($_POST['_csrf']??null))$error='La sesión del formulario venció. Recarga la página e intenta nuevamente.';
    else try{OrganizationService::create($_POST);header('Location: /organizations.php?ok=1');exit;}catch(Throwable $e){$error=user_error_message($e);}
}
$organizations=OrganizationService::all();
?>
