<aside class="v-sidebar"><div class="v-brand"><img class="v-brandmark" src="/assets/quorum-mark.svg" alt=""><span><span class="v-brand-name">QUORUM<small>by INAUDIS</small></span></span></div><nav class="v-nav"><a href="/dashboard.php">⌂ &nbsp; Inicio</a><a href="/elections.php">✓ &nbsp; Votaciones</a><a class="active" href="/organizations.php">▦ &nbsp; Organizaciones</a><a href="/users.php">♙ &nbsp; Usuarios</a><a href="/audit.php">◷ &nbsp; Auditoría</a></nav><div class="v-sidebar-foot"><?=htmlspecialchars($user['name'])?></div></aside>
<div class="v-main"><header class="v-topbar"><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content"><div class="v-headrow"><div><div class="v-kicker">Administración INAUDIS</div><h1 class="v-title">Organizaciones</h1><div class="v-accent-line"></div><p class="v-subtitle">Gestiona los clientes que utilizan la plataforma.</p></div></div>
