<div class="v-grid-2"><section class="v-card v-pad"><h2 style="margin-top:0">Nueva organización</h2><p class="v-muted" style="font-size:13px">Los campos marcados con * son obligatorios.</p><form method="post" class="v-stack"><?=Csrf::input()?><label class="v-label" for="organization-name">Nombre *</label><input id="organization-name" class="v-field" name="name" maxlength="150" required placeholder="Ej.: Sindicato Los Robles" value="<?=htmlspecialchars((string)($_POST['name']??''),ENT_QUOTES)?>"><label class="v-label" for="organization-tax-id">RUT / ID tributario</label><input id="organization-tax-id" class="v-field" name="tax_id" maxlength="32" placeholder="Ej.: 76.000.000-0" value="<?=htmlspecialchars((string)($_POST['tax_id']??''),ENT_QUOTES)?>"><label class="v-label" for="organization-slug">Identificador web *</label><input id="organization-slug" class="v-field" name="slug" maxlength="120" pattern="[a-z0-9-]+" required placeholder="sindicato-los-robles" value="<?=htmlspecialchars((string)($_POST['slug']??''),ENT_QUOTES)?>"><small class="v-muted">Se completa automáticamente. Usa minúsculas, números y guiones.</small><button class="v-btn v-btn-orange">Crear organización</button></form></section>
<section class="v-card v-pad v-table-wrap"><div class="v-section-head"><h2 style="margin:0">Clientes</h2><span class="v-muted"><?=count($organizations)?> organizaciones</span></div><table class="v-table"><thead><tr><th>Nombre</th><th>RUT</th><th>Identificador web</th><th>Estado</th></tr></thead><tbody><?php foreach($organizations as $o):?><tr><td><strong><?=htmlspecialchars($o['name'])?></strong></td><td><?=htmlspecialchars((string)$o['tax_id'])?></td><td><code><?=htmlspecialchars($o['slug'])?></code></td><td><span class="v-status <?=$o['status']==='active'?'v-status-open':'v-status-draft'?>"><?=htmlspecialchars($o['status'])?></span></td></tr><?php endforeach;?></tbody></table></section></div></main></div></div>
<script>(()=>{const name=document.getElementById('organization-name');const slug=document.getElementById('organization-slug');let edited=slug.value!=='';slug.addEventListener('input',()=>edited=slug.value!=='');name.addEventListener('input',()=>{if(edited)return;slug.value=name.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')})})();</script></body></html>
